    # Sort the curves by name
    if self.supported_curves:
        self.supported_curves.sort(key=attrgetter("name"))
    if self.rejected_curves:
        self.rejected_curves.sort(key=attrgetter("name"))

def _detect_http_redirection(http_response: HTTPResponse, server_host_name: str, server_port: int) -> Optional[str]:
    """If the HTTP response contains a redirection to the same server, return the path to the new location."""
    next_location_path = None
    if 300 <= http_response.status < 400:
        location_header = _extract_first_header_value(http_response, "Location")
        if location_header:
            parsed_location = urlsplit(location_header)
            is_relative_url = False if parsed_location.hostname else True
            if is_relative_url:
                # Yes, to a relative URL; follow the redirection
                next_location_path = location_header
            else:
                is_absolute_url_to_same_hostname = parsed_location.hostname == server_host_name
                absolute_url_port = 443 if parsed_location.port is None else parsed_location.port
                is_absolute_url_to_same_port = absolute_url_port == server_port
                if is_absolute_url_to_same_hostname and is_absolute_url_to_same_port:
                    # Yes, to an absolute URL to the same server; follow the redirection
                    next_location_path = f"{parsed_location.path}"
                    if parsed_location.query:
                        next_location_path += f"?{parsed_location.query}"

    return next_location_path

def _extract_first_header_value(response: HTTPResponse, header_name: str) -> Optional[str]:
    raw_header = response.getheader(header_name, None)
    if not raw_header:
        return None

    # Handle headers defined multiple times by picking the first value
    if "," in raw_header:
        raw_header = raw_header.split(",")[0]
    return raw_header

def _parse_hsts_header_from_http_response(response: HTTPResponse) -> Optional[StrictTransportSecurityHeader]:
    raw_hsts_header = _extract_first_header_value(response, "strict-transport-security")
    if not raw_hsts_header:
        return None

    max_age = None
    include_subdomains = False
    preload = False
    for hsts_directive in raw_hsts_header.split(";"):
        hsts_directive = hsts_directive.strip()
        if not hsts_directive:
            # Empty space at the end of the header
            continue

        if "max-age" in hsts_directive:
            max_age = int(hsts_directive.split("max-age=")[1].strip())
        elif "includesubdomains" in hsts_directive.lower():
            # Some websites have a different case for IncludeSubDomains
            include_subdomains = True
        elif "preload" in hsts_directive:
            preload = True
        else:
            _logger.warning(f"Unexpected value in HSTS header: {repr(hsts_directive)}")

    return StrictTransportSecurityHeader(max_age, preload, include_subdomains)

def __init__(self, payload_responses: Dict[RobotPmsPaddingPayloadEnum, List[str]], attempts_count: int) -> None:
    # A mapping of a ROBOT payload enum -> a list of two server responses as text
    for server_responses in payload_responses.values():
        if len(server_responses) != attempts_count:
            raise ValueError()
    self._payload_responses = payload_responses
    self._attempts_count = attempts_count

def __init__(self, server_response: str) -> None:
    # Could be a TLS alert or some data, always as text so we can easily detect different responses
    self.server_response = server_response

def __init__(self, repository_path: Path) -> None:
    available_stores = {}
    # Validate and parse the content of the trust stores folder
    for store_enum in TrustStoreEnum:
        # Parse the YAML file to extract the version
        store_yaml_path = repository_path / f"{store_enum.name.lower()}.yaml"
        store_yaml = store_yaml_path.read_text()
        if store_enum in [TrustStoreEnum.MICROSOFT_WINDOWS, TrustStoreEnum.MOZILLA_NSS]:
            # Use the date_fetched instead as the version
            store_version = store_yaml.split("date_fetched: ", 1)[1].split("\n", 1)[0].strip()
        else:
            store_version = store_yaml.split("version: ", 1)[1].split("\n", 1)[0].strip(" '")

        # Ensure the corresponding PEM file is there
        store_pem_path = repository_path / f"{store_enum.name.lower()}.pem"
        if not store_pem_path.exists():
            raise ValueError(f"Could not find trust store at {store_pem_path}")

        # Store the result
        available_stores[store_enum] = TrustStore(
            path=store_pem_path,
            name=self._STORE_PRETTY_NAMES[store_enum],
            version=store_version,
            ev_oids=[ObjectIdentifier(oid) for oid in _MOZILLA_EV_OIDS]
            if store_enum == TrustStoreEnum.MOZILLA_NSS
            else None,
        )

    self._available_stores = available_stores

def run(self) -> None:
    while True:
        job_to_complete = self._jobs_queue_in.get(block=True)
        if isinstance(job_to_complete, WorkerThreadNoMoreJobsSentinel):
            self._jobs_queue_in.task_done()
            # No more jobs to complete - shutdown the thread
            break

        try:
            return_value = job_to_complete.function_to_call(*job_to_complete.function_arguments)
            self._completed_jobs_queue_out.put(
                CompletedScanJob(
                    parent_server_scan_request_uuid=job_to_complete.parent_server_scan_request_uuid,
                    for_scan_command=job_to_complete.for_scan_command,
                    return_value=return_value,
                    exception=None,
                )
            )
        except Exception as e:
            self._completed_jobs_queue_out.put(
                CompletedScanJob(
                    parent_server_scan_request_uuid=job_to_complete.parent_server_scan_request_uuid,
                    for_scan_command=job_to_complete.for_scan_command,
                    return_value=None,
                    exception=e,
                )
            )
        self._jobs_queue_in.task_done()

def start_work(self, server_scan_requests: List[ServerScanRequest]) -> None:
    assert not self.has_started_work
    self.has_started_work = True

    # Start the threads
    for worker_thread in self._all_worker_threads:
        worker_thread.start()

    # Queue the work
    for request in server_scan_requests:
        self._scan_requests_queue.put(request)

    # Notify workers when all work as been completed
    for _ in self._all_worker_threads:
        self._scan_requests_queue.put(_NoMoreWorkSentinel())

def run(self) -> None:
    while True:
        scan_request = self._scan_requests_queue_in.get(block=True)

        # If there are no more jobs to complete, notify the parent and shutdown the thread
        if isinstance(scan_request, _NoMoreWorkSentinel):
            self._results_queue_out.put(_NoMoreWorkSentinel())
            self._scan_requests_queue_in.task_done()
            return

        # Otherwise process the job
        try:
            tls_probing_result = check_connectivity_to_server(
                server_location=scan_request.server_location,
                network_configuration=scan_request.network_configuration,
            )
            self._results_queue_out.put((scan_request, tls_probing_result))
        except ConnectionToServerFailed as e:
            self._results_queue_out.put((scan_request, e))

        self._scan_requests_queue_in.task_done()

def queue_scans(self, server_scan_requests: List[ServerScanRequest]) -> None:
    if self._has_started_work:
        raise ValueError("Already submitted scan requests")

    if not server_scan_requests:
        raise ValueError("Submitted emtpy list of server_scan_requests")

    # Start with connectivity testing
    self._connectivity_tester.start_work(server_scan_requests)

def __init__(self, concurrent_server_scans_count: int) -> None:
    if concurrent_server_scans_count < 1:
        raise ValueError()

    self._scan_requests_queue: _ScanRequestsQueueType = queue.Queue()
    self._results_queue: _ResultsQueueType = queue.Queue()
    self._all_worker_threads = [
        _ConnectivityTesterThread(
            scan_requests_queue_in=self._scan_requests_queue,
            results_queue_out=self._results_queue,
        )
        for _ in range(concurrent_server_scans_count)
    ]
    self.has_started_work = False

