def command_line_parsed(self, parsed_command_line: ParsedCommandLine) -> None:
    self._file_to.write("\n")
    self._file_to.write(self._format_title("Checking connectivity to server(s)"))
    self._file_to.write("\n")

    for bad_server_str in parsed_command_line.invalid_servers:
        self._file_to.write(
            f"   {bad_server_str.server_string:<35} => ERROR: {bad_server_str.error_message};"
            f" discarding scan.\n"
        )

def server_scan_completed(self, server_scan_result: ServerScanResult) -> None:
    if server_scan_result.scan_status != ServerScanStatusEnum.COMPLETED:
        # Nothing to print here if the scan was not completed
        return
    assert server_scan_result.scan_result  # Must be set if scan_status == ServerScanStatusEnum.COMPLETED

    # Generate the console output for each scan command
    scan_command_results_str = ""
    for result_field in fields(server_scan_result.scan_result):
        scan_command = ScanCommand(result_field.name)
        scan_command_attempt = getattr(server_scan_result.scan_result, scan_command)

        if scan_command_attempt.status == ScanCommandAttemptStatusEnum.COMPLETED:
            scan_command_results_str += "\n"
            cli_connector_cls = ScanCommandsRepository.get_implementation_cls(scan_command).cli_connector_cls
            for line in cli_connector_cls.result_to_console_output(scan_command_attempt.result):
                scan_command_results_str += line + "\n"

        elif scan_command_attempt.status == ScanCommandAttemptStatusEnum.ERROR:
            scan_command_results_str += scan_command_error_as_console_output(
                server_scan_result.server_location, scan_command, scan_command_attempt
            )

        elif scan_command_attempt.status == ScanCommandAttemptStatusEnum.NOT_SCHEDULED:
            pass

        else:
            raise ValueError("Should never happen")

    # Also display the server that was scanned
    server_location = server_scan_result.server_location
    network_route = _server_location_to_network_route(server_location)
    scan_txt = f"Scan Results For {server_location.display_string} - {network_route}"
    self._file_to.write("\n\n" + self._format_title(scan_txt) + scan_command_results_str)

def all_server_scans_completed(self) -> None:
    scans_duration = datetime.utcnow() - self._date_scans_started
    self._file_to.write("\n")
    self._file_to.write(
        self._format_title(f"Scans Completed in {scans_duration.seconds}.{scans_duration.microseconds} s")
    )
    if self._json_path_out:
        self._file_to.write(f'\n       Wrote JSON output to "{self._json_path_out}".\n')

def _server_location_to_network_route(server_location: ServerNetworkLocation) -> str:
    if server_location.connection_type == ConnectionTypeEnum.VIA_HTTP_PROXY:
        # We do not know the server's IP address if going through a proxy
        assert server_location.http_proxy_settings
        network_route = "HTTP proxy at {}:{}".format(
            server_location.http_proxy_settings.hostname, server_location.http_proxy_settings.port
        )
    elif server_location.connection_type == ConnectionTypeEnum.DIRECT:
        assert server_location.ip_address
        network_route = server_location.ip_address
    else:
        raise ValueError("Should never happen")
    return network_route

def parse_command_line(self) -> ParsedCommandLine:
    """Parses the command line used to launch SSLyze."""
    args_command_list = self._parser.parse_args()
    args_target_list = []

    if args_command_list.update_trust_stores:
        # Just update the trust stores and do nothing
        TrustStoresRepository.update_default()
        raise TrustStoresUpdateCompleted()

    # Handle the --targets_in command line and fill args_target_list
    if args_command_list.targets_in:
        try:  # Read targets from a file
            with open(args_command_list.targets_in) as f:
                for target in f.readlines():
                    if target.strip():  # Ignore empty lines
                        if not target.startswith("#"):  # Ignore comment lines
                            args_target_list.append(target.strip())
        except IOError:
            raise CommandLineParsingError(f"Can't read targets from input file '{args_command_list.targets_in}'")

    for target in args_command_list.target:
        args_target_list.append(target)

    if not args_target_list:
        raise CommandLineParsingError("No targets to scan.")

    # Handle the case when no scan commands have been specified: run --mozilla-config=intermediate by default
    if not args_command_list.mozilla_config:
        did_user_enable_some_scan_commands = False
        for scan_command in ScanCommandsRepository.get_all_scan_commands():
            cli_connector_cls = ScanCommandsRepository.get_implementation_cls(scan_command).cli_connector_cls
            is_scan_cmd_enabled, _ = cli_connector_cls.find_cli_options_in_command_line(args_command_list.__dict__)
            if is_scan_cmd_enabled:
                did_user_enable_some_scan_commands = True
                break

        if not did_user_enable_some_scan_commands:
            setattr(args_command_list, "mozilla_config", MozillaTlsConfigurationEnum.INTERMEDIATE.value)

    # Enable the commands needed by --mozilla-config
    check_against_mozilla_config: Optional[MozillaTlsConfigurationEnum] = None
    if args_command_list.mozilla_config:
        if args_command_list.mozilla_config == "disable":
            check_against_mozilla_config = None
        else:
            check_against_mozilla_config = MozillaTlsConfigurationEnum(args_command_list.mozilla_config)

        for scan_cmd in SCAN_COMMANDS_NEEDED_BY_MOZILLA_CHECKER:
            cli_connector_cls = ScanCommandsRepository.get_implementation_cls(scan_cmd).cli_connector_cls
            setattr(args_command_list, cli_connector_cls._cli_option, True)

    # Handle JSON settings
    should_print_json_to_console = False
    json_path_out: Optional[Path] = None
    if args_command_list.json_file:
        if args_command_list.json_file == "-":
            if args_command_list.quiet:
                raise CommandLineParsingError("Cannot use --quiet with --json_out -.")
            should_print_json_to_console = True
        else:
            json_path_out = Path(args_command_list.json_file).absolute()

    # Sanity checks on the client cert options
    client_auth_creds = None
    if bool(args_command_list.cert) ^ bool(args_command_list.key):
        raise CommandLineParsingError("No private key or certificate file were given. See --cert and --key.")

    elif args_command_list.cert:
        # Private key formats
        if args_command_list.keyform == "DER":
            key_type = OpenSslFileTypeEnum.ASN1
        elif args_command_list.keyform == "PEM":
            key_type = OpenSslFileTypeEnum.PEM

        # Let's try to open the cert and key files
        try:
            client_auth_creds = ClientAuthenticationCredentials(
                certificate_chain_path=Path(args_command_list.cert),
                key_path=Path(args_command_list.key),
                key_password=args_command_list.keypass,
                key_type=key_type,
            )
        except ValueError as e:
            raise CommandLineParsingError("Invalid client authentication settings: {}.".format(e.args[0]))

    # HTTP CONNECT proxy
    http_proxy_settings = None
    if args_command_list.https_tunnel:
        try:
            http_proxy_settings = HttpProxySettings.from_url(args_command_list.https_tunnel)
        except ValueError as e:
            raise CommandLineParsingError("Invalid proxy URL for --https_tunnel: {}.".format(e.args[0]))

    # Create the server location objects for each specified servers
    good_servers: List[Tuple[ServerNetworkLocation, ServerNetworkConfiguration]] = []
    invalid_server_strings: List[InvalidServerStringError] = []
    for server_string in args_target_list:
        try:
            # Parse the string supplied via the CLI for this server
            (
                hostname,
                ip_address,
                port,
            ) = CommandLineServerStringParser.parse_server_string(server_string)
        except InvalidServerStringError as e:
            # The server string is malformed
            invalid_server_strings.append(e)
            continue

        # If not port number was supplied, assume 443
        final_port = port if port else 443

        # Figure out how we're going to connect to the server
        server_location: ServerNetworkLocation
        if http_proxy_settings:
            # Connect to the server via an HTTP proxy
            # A limitation when using the CLI is that only one http_proxy_settings can be specified for all servers
            server_location = ServerNetworkLocation(
                hostname=hostname,
                port=final_port,
                http_proxy_settings=http_proxy_settings,
            )
        else:
            # Connect to the server directly
            if ip_address:
                server_location = ServerNetworkLocation(
                    hostname=hostname,
                    port=final_port,
                    ip_address=ip_address,
                )
            else:
                # No IP address supplied - do a DNS lookup
                try:
                    server_location = ServerNetworkLocation(
                        hostname=hostname,
                        port=final_port,
                    )
                except ServerHostnameCouldNotBeResolved:
                    invalid_server_strings.append(
                        InvalidServerStringError(
                            server_string=f"{hostname}:{final_port}",
                            error_message=f"Could not resolve hostname {hostname}",
                        )
                    )
                    continue

        # Figure out extra network config for this server
        # Opportunistic TLS
        opportunistic_tls: Optional[ProtocolWithOpportunisticTlsEnum] = None
        if args_command_list.starttls:
            if args_command_list.starttls == "auto":
                # Special value to auto-derive the protocol from the port number
                opportunistic_tls = ProtocolWithOpportunisticTlsEnum.from_default_port(final_port)
            elif args_command_list.starttls in _STARTTLS_PROTOCOL_DICT:
                opportunistic_tls = _STARTTLS_PROTOCOL_DICT[args_command_list.starttls]
            else:
                raise CommandLineParsingError(
                    f"StartTLS should be one of: auto, {', '.join(_STARTTLS_PROTOCOL_DICT.keys())}."
                )

        try:
            sni_hostname = args_command_list.sni if args_command_list.sni else hostname
            network_config = ServerNetworkConfiguration(
                tls_opportunistic_encryption=opportunistic_tls,
                tls_server_name_indication=sni_hostname,
                tls_client_auth_credentials=client_auth_creds,
                xmpp_to_hostname=args_command_list.xmpp_to,
            )
            good_servers.append((server_location, network_config))
        except InvalidServerNetworkConfigurationError as e:
            raise CommandLineParsingError(e.args[0])

    # Figure out global network settings
    concurrent_server_scans_limit = None
    per_server_concurrent_connections_limit = None
    if args_command_list.https_tunnel:
        # All the connections will go through a single proxy; only scan one server at a time to not DOS the proxy
        concurrent_server_scans_limit = 1
    if args_command_list.slow_connection:
        # Go easy on the servers; only open 2 concurrent connections against each server
        per_server_concurrent_connections_limit = 2

    # Figure out the scan commands that are enabled
    scan_commands: Set[ScanCommand] = set()
    scan_commands_extra_arguments_dict: Dict[ScanCommand, plugin_base.ScanCommandExtraArgument] = {}
    for scan_command in ScanCommandsRepository.get_all_scan_commands():
        cli_connector_cls = ScanCommandsRepository.get_implementation_cls(scan_command).cli_connector_cls
        (
            is_scan_cmd_enabled,
            extra_args,
        ) = cli_connector_cls.find_cli_options_in_command_line(args_command_list.__dict__)
        if is_scan_cmd_enabled:
            scan_commands.add(scan_command)
            if extra_args:
                scan_commands_extra_arguments_dict[scan_command] = extra_args
    scan_commands_extra_arguments = ScanCommandsExtraArguments(**scan_commands_extra_arguments_dict)  # type: ignore

    return ParsedCommandLine(
        invalid_servers=invalid_server_strings,
        servers_to_scans=good_servers,
        scan_commands=scan_commands,
        scan_commands_extra_arguments=scan_commands_extra_arguments,
        should_print_json_to_console=should_print_json_to_console,
        json_path_out=json_path_out,
        should_disable_console_output=args_command_list.quiet or args_command_list.json_file == "-",
        concurrent_server_scans_limit=concurrent_server_scans_limit,
        per_server_concurrent_connections_limit=per_server_concurrent_connections_limit,
        check_against_mozilla_config=check_against_mozilla_config,
    )

def from_default_port(cls, port: int) -> Optional["ProtocolWithOpportunisticTlsEnum"]:
    """Given a port number, return the protocol that uses this port number by default."""
    try:
        return _DEFAULT_PORTS[port]
    except KeyError:
        return None

def do_handshake_with_robot(self):  # type: ignore
    """Modified do_handshake() to send a ROBOT payload and return the result."""
    try:
        # Start the handshake using nassl - will throw WantReadError right away
        self._ssl.do_handshake()
    except WantReadError:
        # Send the Client Hello
        len_to_read = self._network_bio.pending()
        while len_to_read:
            # Get the data from the SSL engine
            handshake_data_out = self._network_bio.read(len_to_read)
            # Send it to the peer
            self._sock.send(handshake_data_out)
            len_to_read = self._network_bio.pending()

    # Retrieve the server's response - directly read the underlying network socket
    # Retrieve data until we get to the ServerHelloDone
    # The server may send back a ServerHello, an Alert or a CertificateRequest first
    did_receive_hello_done = False
    remaining_bytes = b""
    while not did_receive_hello_done:
        try:
            tls_record, len_consumed = TlsRecordParser.parse_bytes(remaining_bytes)
            remaining_bytes = remaining_bytes[len_consumed::]
        except NotEnoughData:
            # Try to get more data
            raw_ssl_bytes = self._sock.recv(16381)
            if not raw_ssl_bytes:
                # No data?
                break

            remaining_bytes = remaining_bytes + raw_ssl_bytes
            continue

        if isinstance(tls_record, TlsHandshakeRecord):
            # Does the record contain a ServerDone message?
            for handshake_message in tls_record.subprotocol_messages:
                if handshake_message.handshake_type == TlsHandshakeTypeByte.SERVER_DONE:
                    did_receive_hello_done = True
                    break
            # If not, it could be a ServerHello, Certificate or a CertificateRequest if the server requires client auth
        elif isinstance(tls_record, TlsAlertRecord):
            # Server returned a TLS alert
            break
        else:
            raise ValueError("Unknown record? Type {}".format(tls_record.header.type))

    if did_receive_hello_done:
        # Send a special Client Key Exchange Record as the payload
        self._sock.send(self._robot_cke_record.to_bytes())

        if self._robot_should_finish_handshake:
            # Then send a CCS record
            ccs_record = TlsChangeCipherSpecRecord.from_parameters(
                tls_version=tls_parser.tls_version.TlsVersionEnum[self._ssl_version.name]
            )
            self._sock.send(ccs_record.to_bytes())

            # Lastly send a Finished record
            finished_record_bytes = _RobotTlsRecordPayloads.get_finished_record_bytes(self._ssl_version)
            self._sock.send(finished_record_bytes)

        # Return whatever the server sent back by raising an exception
        # The goal is to detect similar/different responses
        while True:
            try:
                tls_record, len_consumed = TlsRecordParser.parse_bytes(remaining_bytes)
                remaining_bytes = remaining_bytes[len_consumed::]
            except NotEnoughData:
                # Try to get more data
                try:
                    raw_ssl_bytes = self._sock.recv(16381)
                    if not raw_ssl_bytes:
                        # No data?
                        raise ServerResponseToRobot("No data")
                except socket.error as e:
                    # Server closed the connection after receiving the CCS payload
                    raise ServerResponseToRobot("socket.error {}".format(str(e)))

                remaining_bytes = remaining_bytes + raw_ssl_bytes
                continue

            if isinstance(tls_record, TlsAlertRecord):
                raise ServerResponseToRobot(
                    "TLS Alert {} {}".format(tls_record.alert_description, tls_record.alert_severity)
                )
            else:
                break

        raise ServerResponseToRobot("Ok")

def verified_certificate_chain(self) -> Optional[List[Certificate]]:
    """Get one of the verified certificate chains if one was successfully built using any of the trust stores."""
    for path_result in self.path_validation_results:
        if path_result.was_validation_successful:
            return path_result.verified_certificate_chain
    return None

def verified_certificate_chain_as_pem(self) -> Optional[List[str]]:
    if self.verified_certificate_chain is None:
        return None

    pem_certs = []
    for certificate in self.verified_certificate_chain:
        pem_certs.append(certificate.public_bytes(Encoding.PEM).decode("ascii"))
    return pem_certs

def received_certificate_chain_as_pem(self) -> List[str]:
    pem_certs = []
    for certificate in self.received_certificate_chain:
        pem_certs.append(certificate.public_bytes(Encoding.PEM).decode("ascii"))
    return pem_certs

def _certificate_matches_hostname(certificate: Certificate, server_hostname: str) -> bool:
    """Verify that the certificate was issued for the given hostname."""
    # Extract the names from the certificate to create the properly-formatted dictionary
    from sslyze.plugins.certificate_info._certificate_utils import get_common_names
    from sslyze.plugins.certificate_info._certificate_utils import parse_subject_alternative_name_extension
    try:
        cert_subject = certificate.subject
    except ValueError:
        # Cryptography could not parse the certificate https://github.com/nabla-c0d3/sslyze/issues/495
        return False

    subj_alt_name_ext = parse_subject_alternative_name_extension(certificate)
    subj_alt_name_as_list = [("DNS", name) for name in subj_alt_name_ext.dns_names]
    subj_alt_name_as_list.extend([("IP Address", ip) for ip in subj_alt_name_ext.ip_addresses])

    certificate_names = {
        "subject": (tuple([("commonName", name) for name in get_common_names(cert_subject)]),),
        "subjectAltName": tuple(subj_alt_name_as_list),
    }
    # CertificateError is raised on failure
    try:
        match_hostname(certificate_names, server_hostname)  # type: ignore
        return True
    except CertificateError:
        return False

def is_certificate_extended_validation(self, certificate: Certificate) -> bool:
    """Is the supplied server certificate EV?"""
    if not self.ev_oids:
        raise ValueError("No EV OIDs supplied for {} store - cannot detect EV certificates".format(self.name))

    try:
        cert_policies_ext = certificate.extensions.get_extension_for_oid(ExtensionOID.CERTIFICATE_POLICIES)
    except ExtensionNotFound:
        return False

    cert_policies_value = cast(CertificatePolicies, cert_policies_ext.value)
    for policy in cert_policies_value:
        if policy.policy_identifier in self.ev_oids:
            return True
    return False

def verify_certificate_chain(self, certificate_chain_as_pem: List[str]) -> PathValidationResult:
    certificate = crypto.load_certificate(
        buffer=certificate_chain_as_pem[0].encode("ascii"), type=crypto.FILETYPE_PEM
    )
    chain = [
        crypto.load_certificate(buffer=cert.encode("ascii"), type=crypto.FILETYPE_PEM)
        for cert in certificate_chain_as_pem[1::]
    ]
    x509_store_ctx = crypto.X509StoreContext(store=self._x509_store, certificate=certificate, chain=chain)

    verified_chain: Optional[List[Certificate]]
    error_message: Optional[str]
    try:
        verified_chain_as_x509s = x509_store_ctx.get_verified_chain()
        verified_chain = [x509.to_cryptography() for x509 in verified_chain_as_x509s]
        error_message = None
    except crypto.X509StoreContextError as exc:
        verified_chain = None
        error_message = exc.args[0]

    return PathValidationResult(
        trust_store=self, verified_certificate_chain=verified_chain, openssl_error_string=error_message
    )

def _get_script_dir(follow_symlinks: bool = True) -> Path:
    # Getting the path to the trust stores is tricky due to subtle differences on OS X, Linux and Windows
    if getattr(sys, "frozen", False):
        # py2exe, PyInstaller, cx_Freeze
        path = Path(sys.executable).absolute()
    else:
        path = Path(inspect.getabsfile(_get_script_dir))
    if follow_symlinks:
        path = Path(realpath(path))
    return path.parent

def get_default(cls) -> "TrustStoresRepository":
    # Not thread-safe
    if cls._DEFAULT_REPOSITORY is None:
        cls._DEFAULT_REPOSITORY = cls(cls._DEFAULT_TRUST_STORES_PATH)
    return cls._DEFAULT_REPOSITORY

def _open_socket_for_direct_connection(server_location: ServerNetworkLocation, network_timeout: int) -> socket.socket:
    assert server_location.ip_address
    # Exceptions get caught/processed by the caller
    return socket.create_connection((server_location.ip_address, server_location.port), timeout=network_timeout)

def _open_socket(server_location: ServerNetworkLocation, network_timeout: int) -> socket.socket:
    if server_location.connection_type == ConnectionTypeEnum.VIA_HTTP_PROXY:
        return _open_socket_for_connection_via_http_proxy(server_location, network_timeout)
    elif server_location.connection_type == ConnectionTypeEnum.DIRECT:
        return _open_socket_for_direct_connection(server_location, network_timeout)
    else:
        raise ValueError()

def _do_pre_handshake(self) -> None:
    try:
        sock = _open_socket(self._server_location, self._network_configuration.network_timeout)
    # Re-raise any proxy error with additional context/info
    except _ConnectionToHttpProxyTimedOut:
        raise ConnectionToHttpProxyTimedOut(
            server_location=self._server_location,
            network_configuration=self._network_configuration,
            error_message="Connection to HTTP Proxy timed out",
        )
    except _HttpProxyRejectedConnection as e:
        raise HttpProxyRejectedConnection(
            server_location=self._server_location,
            network_configuration=self._network_configuration,
            error_message=e.args[0],
        )
    except _ConnectionToHttpProxyFailed:
        raise ConnectionToHttpProxyFailed(
            server_location=self._server_location,
            network_configuration=self._network_configuration,
            error_message="Connection to the HTTP proxy failed",
        )

    # Do the Opportunistic/StartTLS negotiation if needed
    if self._network_configuration.tls_opportunistic_encryption:
        opportunistic_tls_helper = get_opportunistic_tls_helper(
            self._network_configuration.tls_opportunistic_encryption, self._network_configuration.xmpp_to_hostname
        )
        try:
            opportunistic_tls_helper.prepare_socket_for_tls_handshake(sock)
        except OpportunisticTlsError as e:
            raise ServerRejectedOpportunisticTlsNegotiation(
                server_location=self._server_location,
                error_message=e.args[0],
                network_configuration=self._network_configuration,
            )

    # Pass the connected socket to the SSL client
    self.ssl_client.set_underlying_socket(sock)

def prepare_socket_for_tls_handshake(self, sock: socket.socket) -> None:
    """Send the right protocol-specific requests to prepare the server for the TLS handshake."""
    pass

def prepare_socket_for_tls_handshake(self, sock: socket.socket) -> None:
    sock.send(self.START_TLS_CMD)
    data = sock.recv(2048)
    if self.START_TLS_OK not in data and self.START_TLS_OK_APACHEDS not in data and self.START_TLS_OK2 not in data:
        raise OpportunisticTlsError(f"LDAP AUTH TLS was rejected; returned: {repr(data)}")

def prepare_socket_for_tls_handshake(self, sock: socket.socket) -> None:
    sock.send(self.START_TLS_CMD)
    data = sock.recv(4)
    if not data or len(data) != 4 or data[:2] != b"\x03\x00":
        raise OpportunisticTlsError(self.ERR_NO_STARTTLS)
    packet_len = struct.unpack(">H", data[2:])[0] - 4
    data = sock.recv(packet_len)

    if not data or len(data) != packet_len:
        raise OpportunisticTlsError(self.ERR_NO_STARTTLS)

def prepare_socket_for_tls_handshake(self, sock: socket.socket) -> None:
    # Grab the banner
    if self.SHOULD_WAIT_FOR_SERVER_BANNER:
        sock.recv(2048)

    # Send Start TLS
    sock.send(self.START_TLS_CMD)
    if self.START_TLS_OK not in sock.recv(2048):
        raise OpportunisticTlsError(self.ERR_NO_STARTTLS)

def from_orm(cls, scan_result: CipherSuitesScanResult) -> "CipherSuitesScanResultAsJson":
    return cls(
        tls_version_used=scan_result.tls_version_used.name,
        is_tls_version_supported=scan_result.is_tls_version_supported,
        accepted_cipher_suites=[
            _CipherSuiteAcceptedByServerAsJson.from_orm(ciph) for ciph in scan_result.accepted_cipher_suites
        ],
        rejected_cipher_suites=[
            _CipherSuiteRejectedByServerAsJson.from_orm(ciph) for ciph in scan_result.rejected_cipher_suites
        ],
    )

def from_orm(cls, public_key: Any) -> "_PublicKeyAsJson":
    try:
        public_key_size = public_key.key_size  # type: ignore
    except AttributeError:
        public_key_size = None

    return cls(
        algorithm=public_key.__class__.__name__,
        key_size=public_key_size,
        # EC-only fields
        ec_curve_name=public_key.curve.name if isinstance(public_key, EllipticCurvePublicKey) else None,
        ec_x=public_key.public_numbers().x if isinstance(public_key, EllipticCurvePublicKey) else None,
        ec_y=public_key.public_numbers().y if isinstance(public_key, EllipticCurvePublicKey) else None,
        # RSA-only fields
        rsa_e=public_key.public_numbers().e if isinstance(public_key, RSAPublicKey) else None,
        rsa_n=public_key.public_numbers().n if isinstance(public_key, RSAPublicKey) else None,
    )

def from_orm(cls, oid: ObjectIdentifier) -> "_ObjectIdentifierAsJson":
    return cls(
        name=oid._name,  # type: ignore
        dotted_string=oid.dotted_string,
    )

def from_orm(cls, name_attribute: NameAttribute) -> "_NameAttributeAsJson":

    return cls(
        oid=_ObjectIdentifierAsJson.from_orm(name_attribute.oid),
        value=name_attribute.value if isinstance(name_attribute.value, str) else str(name_attribute.value),
        rfc4514_string=name_attribute.rfc4514_string(),
    )

def from_orm(cls, name: Name) -> "_X509NameAsJson":
    return cls(
        rfc4514_string=name.rfc4514_string(), attributes=[_NameAttributeAsJson.from_orm(attr) for attr in name]
    )

def from_orm(cls, ocsp_response: ocsp.OCSPResponse) -> "_OcspResponseAsJson":
    response_status = ocsp_response.response_status.name
    if ocsp_response.response_status != ocsp.OCSPResponseStatus.SUCCESSFUL:
        return cls(
            response_status=response_status,
            certificate_status=None,
            revocation_time=None,
            produced_at=None,
            this_update=None,
            next_update=None,
            serial_number=None,
        )
    else:
        return cls(
            response_status=response_status,
            certificate_status=ocsp_response.certificate_status.name,
            revocation_time=ocsp_response.revocation_time,
            produced_at=ocsp_response.produced_at,
            this_update=ocsp_response.this_update,
            next_update=ocsp_response.next_update,
            serial_number=ocsp_response.serial_number,
        )

def from_url(cls, proxy_url: str) -> "HttpProxySettings":
    parsed_url = urlparse(proxy_url)
    if not parsed_url.netloc or not parsed_url.hostname:
        raise ValueError("Invalid Proxy URL")

    if parsed_url.scheme == "http":
        default_port = 80
    elif parsed_url.scheme == "https":
        default_port = 443
    else:
        raise ValueError("Invalid URL scheme")

    port = parsed_url.port if parsed_url.port else default_port
    return cls(parsed_url.hostname, port, parsed_url.username, parsed_url.password)

def proxy_authorization_header(self) -> Optional[str]:
    if not self.basic_auth_user:
        return None
    if not self.basic_auth_password:
        raise ValueError("No password configured for Basic Auth")

    basic_auth_token = b64encode(f"{quote(self.basic_auth_user)}:{quote(self.basic_auth_password)}".encode("utf-8"))
    return basic_auth_token.decode("utf-8")

def display_string(self) -> str:
    """How to display this location to a user."""
    return f"{self.hostname}:{self.port}"

def connection_type(self) -> ConnectionTypeEnum:
    if self.ip_address:
        return ConnectionTypeEnum.DIRECT
    elif self.http_proxy_settings:
        return ConnectionTypeEnum.VIA_HTTP_PROXY
    else:
        raise ValueError("Should never happen")

def _do_dns_lookup(hostname: str, port: int) -> str:
    try:
        addr_infos = socket.getaddrinfo(hostname, port, socket.AF_UNSPEC, socket.IPPROTO_IP)
    except (socket.gaierror, IndexError, ConnectionError):
        raise ServerHostnameCouldNotBeResolved(f"Could not resolve {hostname}")

    family, socktype, proto, canonname, sockaddr = addr_infos[0]

    # By default use the first DNS entry, IPv4 or IPv6
    tentative_ip_addr = sockaddr[0]

    # But try to use IPv4 if we have both IPv4 and IPv6 addresses, to work around buggy networks
    for family, socktype, proto, canonname, sockaddr in addr_infos:
        if family == socket.AF_INET:
            tentative_ip_addr = sockaddr[0]

    return tentative_ip_addr

def __post_init__(self) -> None:
    if self.tls_opportunistic_encryption in [
        ProtocolWithOpportunisticTlsEnum.XMPP,
        ProtocolWithOpportunisticTlsEnum.XMPP_SERVER,
    ]:
        if not self.xmpp_to_hostname:
            # Official workaround for frozen: https://docs.python.org/3/library/dataclasses.html#frozen-instances
            # If no XMPP to hostname was supplied, used the ones from SNI
            object.__setattr__(self, "xmpp_to_hostname", self.tls_server_name_indication)
    else:
        if self.xmpp_to_hostname:
            raise InvalidServerNetworkConfigurationError("Can only specify xmpp_to for the XMPP StartTLS protocol.")

def _parse_ipv4_server_string(cls, server_str: str) -> Tuple[str, Optional[int]]:
    host = server_str
    port = None
    if ":" in server_str:
        host = (server_str.split(":"))[0]  # hostname or ipv4 address
        try:
            port = int((server_str.split(":"))[1])
        except ValueError:  # Port is not an int
            raise InvalidServerStringError(server_string=server_str, error_message=cls.SERVER_STRING_ERROR_BAD_PORT)

    return host, port

def _parse_all_cipher_suites_with_legacy_openssl(tls_version: TlsVersionEnum) -> Set[str]:
    ssl_client = LegacySslClient(ssl_version=OpenSslVersionEnum(tls_version.value))
    # Disable SRP and PSK cipher suites as they need a special setup in the client and are never used
    ssl_client.set_cipher_list("ALL:COMPLEMENTOFALL:-PSK:-SRP")
    return set(ssl_client.get_cipher_list())

def get_all_cipher_suites(cls, tls_version: TlsVersionEnum) -> Set[CipherSuite]:
    """Get the list of cipher suites supported by OpenSSL for the given SSL/TLS version."""
    return cls._ALL_CIPHER_SUITES[tls_version]

def get_cipher_suite_with_openssl_name(cls, tls_version: TlsVersionEnum, openssl_name: str) -> CipherSuite:
    for cipher_suite in cls.get_all_cipher_suites(tls_version):
        if cipher_suite.openssl_name == openssl_name:
            return cipher_suite
    raise ValueError(f"Could not find a cipher suite with the supplied name: {openssl_name}")

def _set_cipher_suite_string(tls_version: TlsVersionEnum, cipher_suite_str: str, ssl_client: BaseSslClient) -> None:
    # Only enable the cipher suite to test; not trivial anymore since OpenSSL 1.1.1 and TLS 1.3
    if isinstance(ssl_client, SslClient):
        # With the modern OpenSSL client we have to manage TLS 1.3-specific cipher functions
        if tls_version == TlsVersionEnum.TLS_1_3:
            ssl_client.set_ciphersuites(cipher_suite_str)  # TLS 1.3 method
        else:
            ssl_client.set_cipher_list(cipher_suite_str)  # Legacy method
    elif isinstance(ssl_client, LegacySslClient):
        # With the legacy OpenSSL client, nothing special to do
        ssl_client.set_cipher_list(cipher_suite_str)
    else:
        raise RuntimeError("Should never happen")

def parse_subject_alternative_name_extension(certificate: Certificate) -> SubjectAlternativeNameExtension:
    try:
        san_ext = certificate.extensions.get_extension_for_oid(ExtensionOID.SUBJECT_ALTERNATIVE_NAME)
        san_ext_value = cast(SubjectAlternativeName, san_ext.value)
    except ExtensionNotFound:
        return SubjectAlternativeNameExtension(dns_names=[], ip_addresses=[])
    except DuplicateExtension:
        # Fix for https://github.com/nabla-c0d3/sslyze/issues/420
        # Not sure how browsers behave in this case but having a duplicate extension makes the certificate invalid
        # so we just return no SANs (likely to make hostname validation fail, which is fine)
        return SubjectAlternativeNameExtension(dns_names=[], ip_addresses=[])

    dns_names = []
    ip_addresses = []
    for san_value in san_ext_value:
        if isinstance(san_value, IPAddress):
            ip_addresses.append(str(san_value.value))
        elif isinstance(san_value, DNSName):
            dns_names.append(san_value.value)
        else:
            pass

    return SubjectAlternativeNameExtension(dns_names=dns_names, ip_addresses=ip_addresses)

def result_to_console_output(cls, result: "CipherSuitesScanResult") -> List[str]:
    result_as_txt = [cls._format_title(cls._title_in_output)]

    cipher_suites_count = len(result.accepted_cipher_suites) + len(result.rejected_cipher_suites)
    if not result.accepted_cipher_suites:
        result_as_txt.append(
            cls._format_subtitle(
                f"Attempted to connect using {cipher_suites_count} cipher suites;"
                f" the server rejected all cipher suites."
            )
        )
        return result_as_txt

    # Display all cipher suites that were accepted
    result_as_txt.append(cls._format_subtitle(f"Attempted to connect using {cipher_suites_count} cipher suites."))
    result_as_txt.append("")
    result_as_txt.append(
        cls._format_subtitle(
            f"The server accepted the following {len(result.accepted_cipher_suites)} cipher suites:"
        )
    )
    for accepted_cipher in result.accepted_cipher_suites:
        result_as_txt.append(_format_accepted_cipher_suite(accepted_cipher))
    result_as_txt.append("")

    # Display some general comments about the cipher suite configuration
    # These comments only apply to TLS versions below 1.3 because TLS 1.3 removed "bad" cipher suites
    if result.tls_version_used.value < TlsVersionEnum.TLS_1_3.value:
        result_as_txt.append(
            cls._format_subtitle("The group of cipher suites supported by the server has the following properties:")
        )

        # Forward secrecy
        supports_forward_secrecy = False
        for accepted_cipher in result.accepted_cipher_suites:
            if "_DHE_" in accepted_cipher.cipher_suite.name or "_ECDHE_" in accepted_cipher.cipher_suite.name:
                supports_forward_secrecy = True
                break

        result_as_txt.append(
            cls._format_field(
                "Forward Secrecy", "OK - Supported" if supports_forward_secrecy else "INSECURE - Not Supported"
            )
        )

        # Insecure RC4 cipher suites
        supports_rc4 = False
        for accepted_cipher in result.accepted_cipher_suites:
            if "_RC4_" in accepted_cipher.cipher_suite.name:
                supports_rc4 = True
                break
        result_as_txt.append(
            cls._format_field(
                "Legacy RC4 Algorithm", "INSECURE - Supported" if supports_rc4 else "OK - Not Supported"
            )
        )
        result_as_txt.append("")

    return result_as_txt

def _format_accepted_cipher_suite(accepted_cipher: CipherSuiteAcceptedByServer) -> str:
    eph_key = accepted_cipher.ephemeral_key
    if isinstance(eph_key, EcDhEphemeralKeyInfo):
        dh_info = f"ECDH: {eph_key.curve_name} ({eph_key.size} bits)"
    elif isinstance(eph_key, DhEphemeralKeyInfo):
        dh_info = f"DH ({eph_key.size} bits)"
    else:
        dh_info = ""

    return f"        {accepted_cipher.cipher_suite.name:<50}{accepted_cipher.cipher_suite.key_size:<10}{dh_info:<15}"

def is_tls_version_supported(self) -> bool:
    """Is the SSL/TLS version used to connect the server supported by it?"""
    return True if self.accepted_cipher_suites else False

def __post_init__(self) -> None:
    if not self.custom_ca_file.is_file():
        raise ValueError(f'Could not open supplied CA file at "{self.custom_ca_file}"')

def result_to_console_output(cls, result: SessionResumptionSupportScanResult) -> List[str]:
    result_as_txt = [cls._format_title("TLS 1.2 Session Resumption Support")]

    # Resumption with session IDs
    if result.session_id_resumption_result == TlsResumptionSupportEnum.SERVER_IS_TLS_1_3_ONLY:
        session_id_support_txt = "OK - Server only supports TLS 1.3 which doesn't support Session IDs"
    else:
        session_id_support_txt = _resumption_result_to_console_output(
            result.session_id_resumption_result,
            result.session_id_successful_resumptions_count,
            result.session_id_attempted_resumptions_count,
        )
    result_as_txt.append(f"      With Session IDs: {session_id_support_txt}.")

    # Resumption with TLS tickets
    if result.tls_ticket_resumption_result == TlsResumptionSupportEnum.SERVER_IS_TLS_1_3_ONLY:
        tls_ticket_support_txt = "OK - Server only supports TLS 1.3 which doesn't support TLS tickets"
    else:
        tls_ticket_support_txt = _resumption_result_to_console_output(
            result.tls_ticket_resumption_result,
            result.tls_ticket_successful_resumptions_count,
            result.tls_ticket_attempted_resumptions_count,
        )
    result_as_txt.append(f"      With TLS Tickets: {tls_ticket_support_txt}.")

    return result_as_txt

def result_to_console_output(cls, result: RobotScanResult) -> List[str]:
    result_as_txt = [cls._format_title("ROBOT Attack")]

    if result.robot_result == RobotScanResultEnum.VULNERABLE_STRONG_ORACLE:
        robot_txt = "VULNERABLE - Strong oracle, a real attack is possible."
    elif result.robot_result == RobotScanResultEnum.VULNERABLE_WEAK_ORACLE:
        robot_txt = "VULNERABLE - Weak oracle, the attack would take too long."
    elif result.robot_result == RobotScanResultEnum.NOT_VULNERABLE_NO_ORACLE:
        robot_txt = "OK - Not vulnerable."
    elif result.robot_result == RobotScanResultEnum.NOT_VULNERABLE_RSA_NOT_SUPPORTED:
        robot_txt = "OK - Not vulnerable, RSA cipher suites not supported."
    elif result.robot_result == RobotScanResultEnum.UNKNOWN_INCONSISTENT_RESULTS:
        robot_txt = "UNKNOWN - Received inconsistent results."
    else:
        raise ValueError("Should never happen")
    result_as_txt.append(cls._format_field("", robot_txt))
    return result_as_txt

def _get_subject_as_short_text(certificate: Certificate) -> str:
    try:
        final_subject_field = _get_name_as_short_text(certificate.subject)
    except ValueError:
        # Cryptography could not parse the certificate https://github.com/nabla-c0d3/sslyze/issues/495
        final_subject_field = "Invalid Cert: Subject could not be parsed"
    return final_subject_field

def _get_issuer_as_short_text(certificate: Certificate) -> str:
    try:
        final_issuer_field = _get_name_as_short_text(certificate.issuer)
    except ValueError:
        # Cryptography could not parse the certificate https://github.com/nabla-c0d3/sslyze/issues/495
        final_issuer_field = "Invalid Cert: Issuer could not be parsed"
    return final_issuer_field

def _get_name_as_short_text(name_field: x509.Name) -> str:
    """Convert a name field returned by the cryptography module to a string suitable for displaying it to the user."""
    # Name_field is supposed to be a Subject or an Issuer; print the CN if there is one
    from sslyze.plugins.certificate_info._certificate_utils import get_common_names
    common_names = get_common_names(name_field)
    if common_names:
        # We don't support certs with multiple CNs
        return common_names[0]
    else:
        # Otherwise show the whole field
        return name_field.rfc4514_string()
